def feed_rank(posts):
    return sorted(posts, key=lambda p: p.get("likes_count",0)*2 + p.get("comments_count",0)*3 + (50 if p.get("is_friend") else 0), reverse=True)
def suggest():
    return [{"id":str(uuid.uuid4()),"name":n,"city":c,"mutual":m,"avatar":f"https://i.pravatar.cc/150?u={n}"} for n,c,m in [("أحمد علي","عطبرة",5),("سارة محمد","الخرطوم",12),("قصة معقدة","عطبرة",50),("ود حسن حمد","عطبرة",20)]]
def privacy_score(s):
    score=100; recs=[]
    if not s.get("two_factor"): score-=30; recs.append("تفعيل المصادقة الثنائية +30%")
    if s.get("default_audience")=="PUBLIC": score-=15; recs.append("تقييد المنشورات للأصدقاء +15%")
    if not s.get("app_lock"): score-=10; recs.append("تفعيل قفل نور شات +10%")
    return {"score":max(0,score),"status":"ممتاز 🟢" if score>=85 else "جيد 🟡","issues":recs}

